import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.Charset;
import java.util.StringTokenizer;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.io.BufferedReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author mikit
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        LightWriter out = new LightWriter(outputStream);
        CMisterBAndBoringGame solver = new CMisterBAndBoringGame();
        solver.solve(1, in, out);
        out.close();
    }

    static class CMisterBAndBoringGame {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            // out.setBoolLabel(LightWriter.BoolLabel.YES_NO_FIRST_UP);
            int a = in.ints(), b = in.ints(), l = in.ints() - 1, r = in.ints() - 1;

            int min = 26;
            for (char p = 'a'; p <= 'z'; p++) {
                for (char q = (char) ('a' + a); q <= 'z'; q++) {
                    StringBuilder rep = new StringBuilder();
                    for (int i = 0; i < a; i++) rep.append((char) (i + 'a'));
                    for (int i = 0; i < b; i++) rep.append(p);
                    outer:
                    for (int i = 0; i < a; i++) {
                        boolean[] f = new boolean[26];
                        for (int j = b; j < a + b + i; j++) {
                            f[rep.charAt(j) - 'a'] = true;
                        }
                        for (int j = 0; j < 26; j++) {
                            if (!f[j]) {
                                rep.append((char) (j + 'a'));
                                continue outer;
                            }
                        }
                    }
                    for (int i = 0; i < b; i++) rep.append(q);

                    boolean[] flag = new boolean[26];
                    if (r - l + 1 >= 100_000) {
                        for (int i = 0; i < rep.length(); i++) {
                            flag[rep.charAt(i) - 'a'] = true;
                        }
                    } else {
                        for (int i = l; i <= r; i++) {
                            flag[rep.charAt(i % rep.length()) - 'a'] = true;
                        }
                    }

                    //System.out.println(rep);

                    int ans = 0;
                    for (int i = 0; i < 26; i++) if (flag[i]) ans++;
                    min = Math.min(ans, min);
                }
            }
            out.ans(min).ln();
        }

    }

    static class LightScanner {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ints() {
            return Integer.parseInt(string());
        }

    }

    static class LightWriter implements AutoCloseable {
        private final Writer out;
        private boolean autoflush = false;
        private boolean breaked = true;

        public LightWriter(Writer out) {
            this.out = out;
        }

        public LightWriter(OutputStream out) {
            this(new BufferedWriter(new OutputStreamWriter(out, Charset.defaultCharset())));
        }

        public LightWriter print(char c) {
            try {
                out.write(c);
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter print(String s) {
            try {
                out.write(s, 0, s.length());
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter ans(String s) {
            if (!breaked) {
                print(' ');
            }
            return print(s);
        }

        public LightWriter ans(int i) {
            return ans(Integer.toString(i));
        }

        public LightWriter ln() {
            print(System.lineSeparator());
            breaked = true;
            if (autoflush) {
                try {
                    out.flush();
                } catch (IOException ex) {
                    throw new UncheckedIOException(ex);
                }
            }
            return this;
        }

        public void close() {
            try {
                out.close();
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
        }

    }
}


